{
  "registry_id": "slope_external_event_cashflow",
  "registry_version": "2.0.1-design",
  "status": "design_template_not_live_validated",
  "model_id": "jev-1.13.0",
  "sdk_requirement": "typesafe-sdk==0.7.1",
  "sdk_mapping": "For each selected entry, copy entry.question, prefix its instructions with the global_rules text, and construct typesafe_sdk.Choice(**copied_question). Other entry metadata is enforced by the host and is not forwarded as unsupported model instruction fields.",
  "purpose": "Focused evidence and research-routing judgments inside an adaptive external-event investigation. No question estimates a borrower default probability, generates a dollar adjustment, or makes the final lending decision.",
  "global_rules": [
    "Evaluate only the supplied state. Do not use remembered facts about this company, dispute, or later events.",
    "Each semantic call concerns one atomic claim, one target, and one source passage with necessary qualifications. Split multiple claims before evaluation.",
    "If more than one substantive category fits because the input combines claims, select unknown instead of choosing an arbitrary category.",
    "The instruction describes the statement in this evidence. Code applies dates, source eligibility, supersession and financial arithmetic separately.",
    "Source authority and claim posture are separate. An SEC filing can report an allegation or expectation.",
    "No confidence threshold automatically converts a judgment to an accepted fact or a credit decision. Retain all distributions and require the agent to reconcile material contradictions.",
    "Independent questions using the same state may be batched. A question that depends on another answer receives a later request with that answer explicitly included in state.",
    "Question identifiers are application metadata. The complete question must appear in instructions."
  ],
  "state_contract": {
    "semantic": {
      "required": [
        "target",
        "source",
        "passage",
        "atomic_claim"
      ],
      "optional": [
        "definitions",
        "proposed_finding",
        "identified_obligation",
        "identified_activity",
        "identified_cash_pool",
        "identified_offset"
      ],
      "target": "Resolved legal entity plus the specific affiliate, asset, operating activity, or obligation being evaluated.",
      "source": "Source ID, content hash, publisher and document kind. The backend has already checked eligibility.",
      "passage": "Source text and enough surrounding qualifications to preserve meaning.",
      "atomic_claim": "One statement extracted by the reasoning agent; exact source spans remain available.",
      "definitions": "Only the definitions needed for this judgment.",
      "proposed_finding": "One proposition, including entity and asset scope, for supports/contradicts evaluation."
    },
    "routing": {
      "required": [
        "selected_gap",
        "decision_dependency",
        "available_source_categories"
      ],
      "optional": [
        "candidate",
        "known_evidence",
        "previous_unsuccessful_actions"
      ],
      "selected_gap": "One unresolved factual question selected by the primary agent.",
      "decision_dependency": "Which modeled premise or offer comparison would change when this gap is resolved. Any quantitative sensitivity was calculated by the financial engine.",
      "available_source_categories": "Backend-allowed source categories and available document/action summaries. No arbitrary web or filesystem capability is implied.",
      "candidate": "One candidate document or proposed retrieval/customer question with its available description."
    }
  },
  "questions": [
    {
      "id": "entity_scope",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The relationship between the passage and the target legal entity or specific asset/activity must be established.",
      "question": {
        "instructions": "Does the one claim in state.atomic_claim, read with state.passage and state.definitions, apply to state.target? Judge only identity and stated scope, not whether the claim is true. Do not infer that an affiliate's liabilities belong to the parent. If the evidence does not resolve identity or scope, choose unknown.",
        "criteria": {
          "target": "The claim explicitly concerns the specified target entity and, when specified, the target asset, activity or obligation.",
          "different": "The claim explicitly concerns a different entity, asset, activity or obligation, and the supplied evidence does not extend it to the specified target.",
          "unknown": "Identity or scope cannot be resolved, necessary definitions are missing, or multiple targets are combined without a clear application."
        }
      },
      "application": "A target match permits further interpretation; it does not establish liability or the amount of economic exposure. A different or unknown match prevents automatic attribution to the borrower."
    },
    {
      "id": "claim_posture",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The agent needs to distinguish an assertion or expectation from a reported agreement, order or completed event.",
      "question": {
        "instructions": "Classify the single statement state.atomic_claim by what state.passage presents it as. Classify the claim itself, not the document publisher. This input must contain one claim; choose unknown for combined or ambiguous claims. A statement that a party seeks an order is an allegation_or_request, not a court_imposed_requirement. A reported payment or completed manufacturing start is reported_completed_event, not a prediction.",
        "criteria": {
          "allegation_or_request": "A party asserts a disputed factual/legal claim or requests relief; the statement does not report an operative agreement, court requirement or completed event establishing that claim.",
          "court_imposed_requirement": "The statement describes a requirement imposed by an identified court order, rather than a party's requested requirement.",
          "agreed_requirement": "The statement describes an obligation or condition in an agreement between parties, rather than a court-imposed requirement or a report that performance has already occurred.",
          "reported_completed_event": "The statement reports that the identified action or event has occurred, such as a payment, financing receipt or production start, rather than merely being required or expected.",
          "expectation_or_plan": "The statement presents a forecast, expectation, target or plan whose occurrence is not reported as completed or presently required by an identified agreement or order.",
          "unknown": "The statement does not fit one category, has insufficient context, or combines multiple claims with different postures."
        }
      },
      "application": "Record posture separately from source authority. A reported completed event remains a sourced report and can still require reconciliation with contradictory evidence."
    },
    {
      "id": "finding_support",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The primary agent proposes one factual premise for a financial effect, condition or baseline adjustment.",
      "question": {
        "instructions": "Does state.passage, with state.definitions, support the complete single proposition in state.proposed_finding for state.target? Preserve qualifiers, entity scope, claim posture and whether a fact is expected or completed. Do not supply missing amounts, dates, causal steps or facts from memory. Choose unknown if both support and contradiction appear or the passage cannot decide the proposition.",
        "criteria": {
          "supports": "The passage establishes the proposition as worded, including its scope and qualifiers, without requiring an unsupported inference.",
          "contradicts": "The passage establishes an incompatible proposition for the same scope, so the proposed finding cannot accurately describe this passage.",
          "unknown": "The passage is insufficient, ambiguous, internally conflicting, only addresses part of the proposition, or requires outside facts to decide it."
        }
      },
      "application": "This is evidence support for one proposition, not a confidence estimate for the scenario occurring or the borrower defaulting. The agent still reconciles other sources."
    },
    {
      "id": "cash_restriction",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The selected gap concerns access to a specifically identified cash balance, account, receivable proceeds or payout pool.",
      "question": {
        "instructions": "What access condition does the single statement state.atomic_claim in state.passage expressly describe for state.identified_cash_pool? Classify only the described condition; do not determine whether it remains effective at the mission date. A request to freeze funds is not a freeze. A borrowing limit is not automatically a restriction on already-owned cash. If the statement mixes conditions or does not establish one, choose unknown.",
        "criteria": {
          "access_prohibited": "The statement describes an imposed prohibition on access to the entire identified cash pool, rather than a requested or merely possible restriction.",
          "access_limited": "The statement describes imposed partial access, permitted uses, an amount cap or a stated release condition for the identified pool, rather than a complete prohibition.",
          "restriction_released": "The statement reports removal or satisfaction of the identified restriction, rather than a requested release or expected future release.",
          "restriction_requested_only": "The statement only requests, proposes or anticipates a restriction and does not report that it was imposed.",
          "unknown": "No single access condition is established for the identified pool, or the passage combines unresolved conditions."
        }
      },
      "application": "Code handles effective intervals and amounts. A restricted cash pool is not necessarily lost cash, and unknown access is not zero cash."
    },
    {
      "id": "activity_restriction",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The gap concerns whether a specified product, manufacturing activity or sales channel can operate, including production interruptions and planned replacement capacity.",
      "question": {
        "instructions": "What operating-availability state does state.atomic_claim in state.passage describe for state.identified_activity? Classify this one claim, not the whole company. Do not infer current revenue share, sell-through or cash receipts from manufacturing capacity. Do not treat a signed capacity agreement or expected start as completed production. Temporal application to the mission date is performed separately in code. Choose unknown if multiple states are combined or none is established.",
        "criteria": {
          "unavailable": "The statement reports that the identified activity has stopped or is prevented entirely, rather than merely describing a risk of interruption.",
          "limited": "The statement reports that the activity operates only within an identified product, capacity, permission or other constraint; it is not entirely unavailable.",
          "planned_or_conditional": "The statement describes operating availability that depends on a future start, approval, qualification, ramp or other unmet condition; operation is not reported as achieved.",
          "available_or_restored": "The statement reports that the specified activity is operating or has resumed at the scope described, without an unresolved operating constraint stated in this claim.",
          "unknown": "The statement does not establish one operating state, combines different activities/states, or lacks necessary scope."
        }
      },
      "application": "The agent links only the specified activity to supported receipts and costs. Capacity is not demand, revenue or cash. Historical supplier shares do not become current automatic revenue haircuts."
    },
    {
      "id": "obligation_status",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The gap concerns a specified payment obligation such as a disputed payable, settlement, legal expense or debt service.",
      "question": {
        "instructions": "What status does the single statement state.atomic_claim in state.passage establish for state.identified_obligation? Classify the obligation described, not all liabilities of the company. An amount demanded by a counterparty is not automatically an agreed payment. Do not generate a due date, assume immediate payment, or decide whether the amount has already entered the financial baseline. If the status is internally conflicting or combines different obligations, choose unknown.",
        "criteria": {
          "required_unconditional": "The statement describes a fixed payment obligation whose existence does not depend on an unresolved condition and does not report that it has already been satisfied; timing may still be unspecified.",
          "claimed_or_disputed": "The statement describes a demand or contested amount, and does not establish an agreed or ordered unconditional payment of that amount.",
          "conditional": "The statement explicitly makes the payment obligation depend on an unresolved event or condition, rather than presenting it solely as a disputed demand.",
          "reported_satisfied": "The statement reports that the identified obligation has been paid, discharged or otherwise satisfied, rather than merely promising future payment.",
          "unknown": "The statement does not establish one status, omits necessary context, or combines unresolved statuses."
        }
      },
      "application": "Extract amounts and dates separately, then reconcile with opening balances, existing AP and loan schedules. A historical paid amount is not a new forecast outflow."
    },
    {
      "id": "offset_support",
      "version": "2.0.0",
      "role": "semantic",
      "applies_when": "The gap concerns a particular insurance reimbursement, legal-expense funding arrangement, indemnity or other identified source offsetting an expense or exposure.",
      "question": {
        "instructions": "What does state.atomic_claim in state.passage establish about state.identified_offset? Distinguish a documented funding commitment from hoped-for recovery and from money already received. Judge the one identified payment or coverage obligation only. A commitment to finance legal expenses is not unrestricted cash, and being nonrecourse does not make damages recoverable or guaranteed. Choose unknown if the statement combines different statuses or the offset cannot be established.",
        "criteria": {
          "committed_without_stated_unmet_condition": "The statement describes an identified party's commitment or payable obligation covering the specified offset, with no unresolved condition stated in this claim, and does not report the specific payment as already received.",
          "committed_subject_to_condition": "The statement describes a commitment whose availability for this offset expressly depends on a condition not reported as satisfied, and does not report the payment as already received.",
          "possible_or_disputed": "The statement presents the offset as a possibility, demand, disputed entitlement or expectation without an established commitment for this offset.",
          "reported_received_or_paid_for_borrower": "The statement reports that the identified amount has been received or the specified expense has already been paid on the borrower's behalf.",
          "unknown": "The statement does not establish one status or the scope of the offset, or it combines unresolved statuses."
        }
      },
      "application": "The primary agent must establish beneficiary, covered expense, amount, timing and recourse separately. Do not net legal expenses or add a cash inflow beyond the documented coverage."
    },
    {
      "id": "next_source",
      "version": "2.0.0",
      "role": "research_routing",
      "applies_when": "The agent has selected a decision-relevant factual gap and wants to choose an available source category before executing retrieval.",
      "question": {
        "instructions": "For the one factual question in state.selected_gap, which category in state.available_source_categories most directly contains the evidence needed to resolve it? Use state.decision_dependency only to understand the needed premise; do not decide the financing offer. Select only a category explicitly available in state. Choose unknown if the gap combines questions, multiple categories are equally direct, or none can establish the answer. The agent chooses the actual retrieval action after this judgment.",
        "criteria": {
          "court_order": "An available court order or docket record is the most direct source for the specific operative court action or litigation status being asked about.",
          "executed_agreement": "An available executed loan, settlement, supplier, funding or other agreement is the most direct source for the contractual obligation or condition being asked about.",
          "financial_record": "An available financial statement, debt statement, accounting exhibit or bank record is the most direct source for the realized financial amount or balance being asked about.",
          "marketplace_record": "An available marketplace statement, payout record or account notice is the most direct source for the specified platform sales, payouts or account restriction.",
          "official_business_disclosure": "An available company or regulator disclosure is the most direct source for the specified reported business event, and the gap is not more directly resolved by another available listed category.",
          "borrower_question": "The needed fact is not established by available records, and a specific borrower-provided document or answer is the most direct feasible next source.",
          "unknown": "No available category can be selected unambiguously, categories are equally direct, or the gap needs decomposition."
        }
      },
      "application": "This routes research, not credit. A borrower question records the exact missing fact, required evidence and consequences under each answer; it never automatically sends a message."
    },
    {
      "id": "candidate_relevance",
      "version": "2.0.0",
      "role": "research_routing",
      "applies_when": "The agent has a selected gap and one candidate source passage, document description or feasible research action to rank.",
      "question": {
        "instructions": "How directly would the evidence available in state.candidate address state.selected_gap? Judge the candidate's stated content or proposed action, not unseen contents and not the importance of the lawsuit. If only a title or snippet is available, do not assume it contains the required answer. Use the most direct single category whose definition is fully supported; choose unknown if the available description cannot establish relevance.",
        "criteria": {
          "resolves_selected_premise": "The candidate contains the specific evidence needed to resolve the selected premise, or proposes a direct question whose requested answer/document would resolve that premise if supplied.",
          "narrows_selected_premise": "The candidate addresses the selected premise and can reduce a specific uncertainty, but another factual element is still required to resolve it.",
          "context_only": "The candidate provides related background but does not resolve or narrow a specific uncertainty in the selected premise.",
          "unrelated": "The candidate is sufficiently described to establish that it does not concern the selected premise or relevant background.",
          "unknown": "The available description is insufficient, contradictory or too broad to place the candidate in one category."
        }
      },
      "application": "Rank direct relevance independently from economic materiality. Code may map these categories to a research queue order; do not map them to loss percentages or approval thresholds."
    }
  ],
  "response_record": {
    "required_fields": [
